-- Captured from BusyMax 0.4.0, 5fbb15a2e103f3ee12627c8ab77974996e60e4d6.
-- Actual AppDatabase onCreate output before CalDAV changes.
CREATE TABLE "accounts" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL, "authority" TEXT NOT NULL, "provider_account_id" TEXT NOT NULL, "credential_kind" TEXT NOT NULL, "provider_profile_version" INTEGER NOT NULL DEFAULT 1, "display_name" TEXT NULL, "email" TEXT NULL, "tenant_id" TEXT NULL, "account_avatar_url" TEXT NULL, "provider_metadata_json" TEXT NULL, "auth_state" TEXT NOT NULL DEFAULT 'signed_out', "calendars_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("calendars_enabled" IN (0, 1)), "tasks_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("tasks_enabled" IN (0, 1)), "granted_scopes" TEXT NOT NULL DEFAULT '', "created_at_utc" TEXT NOT NULL, "updated_at_utc" TEXT NOT NULL, "last_successful_sync_at_utc" TEXT NULL, "last_full_sync_at_utc" TEXT NULL, "task_import_incomplete" INTEGER NOT NULL DEFAULT 0 CHECK ("task_import_incomplete" IN (0, 1)), PRIMARY KEY ("id"), CHECK (provider IN ('google', 'microsoft', 'apple_icloud', 'nextcloud', 'webcal')), CHECK (credential_kind IN ('oauth', 'apple_app_specific_password', 'nextcloud_app_password', 'webcal_subscription')), CHECK ((provider IN ('google', 'microsoft') AND credential_kind = 'oauth') OR (provider = 'apple_icloud' AND credential_kind = 'apple_app_specific_password') OR (provider = 'nextcloud' AND credential_kind = 'nextcloud_app_password') OR (provider = 'webcal' AND credential_kind = 'webcal_subscription')), CHECK (length(trim(authority)) > 0), CHECK (length(trim(provider_account_id)) > 0));
CREATE TABLE "o_auth_transition_accounts" ("account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, PRIMARY KEY ("account_id"));
CREATE TABLE "account_authorizations" ("account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "generation" INTEGER NOT NULL, "summary_json" TEXT NOT NULL, PRIMARY KEY ("account_id"));
CREATE TABLE "authorization_commits" ("account_id" TEXT NOT NULL, "generation" INTEGER NOT NULL, "had_credential" INTEGER NOT NULL CHECK ("had_credential" IN (0, 1)), "previous_active_account_id" TEXT NULL, "previous_native_binding_json" TEXT NULL, PRIMARY KEY ("account_id"));
CREATE TABLE "authorization_generations" ("account_id" TEXT NOT NULL, "generation" INTEGER NOT NULL, PRIMARY KEY ("account_id"));
CREATE TABLE "domain_sync_schedules" ("account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "domain" TEXT NOT NULL, "last_successful_pull_utc" TEXT NULL, "next_passive_pull_utc" TEXT NULL, "cooldown_until_utc" TEXT NULL, PRIMARY KEY ("account_id", "domain"));
CREATE TABLE "dav_account_services" ("account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "canonical_service_uri" TEXT NOT NULL, "canonical_origin" TEXT NOT NULL, "principal_href" TEXT NULL, "calendar_home_href" TEXT NULL, "calendar_user_addresses_json" TEXT NOT NULL DEFAULT '[]', "schedule_inbox_href" TEXT NULL, "schedule_outbox_href" TEXT NULL, "capabilities_json" TEXT NOT NULL DEFAULT '{}', "capabilities_schema_version" INTEGER NOT NULL DEFAULT 1, "provider_profile_version" INTEGER NOT NULL DEFAULT 1, "discovered_at_utc" TEXT NOT NULL, "last_validated_at_utc" TEXT NULL, "last_discovery_error_code" TEXT NULL, PRIMARY KEY ("account_id"));
CREATE TABLE "dav_collections" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "href_key" TEXT NOT NULL, "request_uri" TEXT NOT NULL, "display_name" TEXT NOT NULL, "description" TEXT NULL, "resource_types_json" TEXT NOT NULL DEFAULT '[]', "supported_component_mask" INTEGER NOT NULL DEFAULT 0, "supported_calendar_data_json" TEXT NOT NULL DEFAULT '[]', "supported_reports_json" TEXT NOT NULL DEFAULT '[]', "current_user_privileges_json" TEXT NOT NULL DEFAULT '[]', "owner_href" TEXT NULL, "safe_display_metadata_json" TEXT NULL, "color" TEXT NULL, "sort_order" INTEGER NULL, "calendar_time_zone" TEXT NULL, "calendar_time_zone_id" TEXT NULL, "schedule_transparency" TEXT NULL, "maximum_resource_size" INTEGER NULL, "maximum_instances" INTEGER NULL, "sync_token" TEXT NULL, "ctag" TEXT NULL, "read_only" INTEGER NOT NULL DEFAULT 1 CHECK ("read_only" IN (0, 1)), "event_projection_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("event_projection_enabled" IN (0, 1)), "task_projection_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("task_projection_enabled" IN (0, 1)), "events_selected" INTEGER NOT NULL DEFAULT 1 CHECK ("events_selected" IN (0, 1)), "tasks_selected" INTEGER NOT NULL DEFAULT 1 CHECK ("tasks_selected" IN (0, 1)), "server_missing" INTEGER NOT NULL DEFAULT 0 CHECK ("server_missing" IN (0, 1)), "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), "last_inventory_at_utc" TEXT NULL, "last_sync_at_utc" TEXT NULL, "parser_version" INTEGER NOT NULL DEFAULT 1, "projection_version" INTEGER NOT NULL DEFAULT 1, "created_at_utc" TEXT NOT NULL, "updated_at_utc" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "dav_objects" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "collection_id" TEXT NOT NULL REFERENCES dav_collections (id) ON DELETE CASCADE, "href_key" TEXT NOT NULL, "request_uri" TEXT NOT NULL, "etag" TEXT NULL, "content_type" TEXT NULL, "dominant_component_type" TEXT NULL, "component_mask" INTEGER NOT NULL DEFAULT 0, "primary_uid" TEXT NULL, "raw_ics_body" TEXT NOT NULL, "raw_body_hash" TEXT NOT NULL, "semantic_hash" TEXT NULL, "server_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("server_deleted" IN (0, 1)), "baseline_generation" INTEGER NOT NULL DEFAULT 0, "first_seen_at_utc" TEXT NOT NULL, "last_fetched_at_utc" TEXT NOT NULL, "last_changed_at_utc" TEXT NOT NULL, "last_parse_status" TEXT NOT NULL DEFAULT 'unparsed', "last_parse_error_code" TEXT NULL, "parser_version" INTEGER NOT NULL DEFAULT 1, PRIMARY KEY ("id"));
