CREATE TABLE "tasks" ("account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "task_list_id" TEXT NOT NULL, "id" TEXT NOT NULL, "dav_collection_id" TEXT NULL REFERENCES dav_collections (id) ON DELETE SET NULL, "dav_object_id" TEXT NULL REFERENCES dav_objects (id) ON DELETE SET NULL, "dav_component_id" TEXT NULL REFERENCES dav_object_components (id) ON DELETE SET NULL, "ical_uid" TEXT NULL, "recurrence_id_key" TEXT NULL, "ical_priority" INTEGER NULL, "percent_complete" INTEGER NULL, "task_location" TEXT NULL, "location_latitude" REAL NULL, "location_longitude" REAL NULL, "task_url" TEXT NULL, "task_classification" TEXT NULL, "task_pinned" INTEGER NULL CHECK ("task_pinned" IN (0, 1)), "task_hide_subtasks" INTEGER NULL CHECK ("task_hide_subtasks" IN (0, 1)), "task_hide_completed_subtasks" INTEGER NULL CHECK ("task_hide_completed_subtasks" IN (0, 1)), "task_alarms_json" TEXT NULL, "parent_uid" TEXT NULL, "sort_order" INTEGER NULL, "provider_extension_projection_json" TEXT NULL, "projection_version" INTEGER NOT NULL DEFAULT 1, "kind" TEXT NULL, "etag" TEXT NULL, "title" TEXT NOT NULL, "updated_utc" TEXT NULL, "self_link" TEXT NULL, "parent" TEXT NULL, "position" TEXT NULL, "notes" TEXT NULL, "status" TEXT NULL, "due_utc" TEXT NULL, "completed_utc" TEXT NULL, "provider_status" TEXT NULL, "body_content" TEXT NULL, "body_content_type" TEXT NULL, "microsoft_due_date_time" TEXT NULL, "microsoft_due_time_zone" TEXT NULL, "microsoft_start_date_time" TEXT NULL, "microsoft_start_time_zone" TEXT NULL, "microsoft_reminder_date_time" TEXT NULL, "microsoft_reminder_time_zone" TEXT NULL, "microsoft_is_reminder_on" INTEGER NULL CHECK ("microsoft_is_reminder_on" IN (0, 1)), "microsoft_completed_date_time" TEXT NULL, "microsoft_completed_time_zone" TEXT NULL, "microsoft_checklist_items_json" TEXT NULL, "recurrence_json" TEXT NULL, "importance" TEXT NULL, "categories_json" TEXT NULL, "has_attachments" INTEGER NULL CHECK ("has_attachments" IN (0, 1)), "provider_metadata_json" TEXT NULL, "deleted" INTEGER NULL CHECK ("deleted" IN (0, 1)), "hidden" INTEGER NULL CHECK ("hidden" IN (0, 1)), "links_json" TEXT NULL, "web_view_link" TEXT NULL, "assignment_info_json" TEXT NULL, "raw_json" TEXT NOT NULL, "server_missing" INTEGER NOT NULL DEFAULT 0 CHECK ("server_missing" IN (0, 1)), "local_dirty" INTEGER NOT NULL DEFAULT 0 CHECK ("local_dirty" IN (0, 1)), "pending_delete" INTEGER NOT NULL DEFAULT 0 CHECK ("pending_delete" IN (0, 1)), "pending_move" INTEGER NOT NULL DEFAULT 0 CHECK ("pending_move" IN (0, 1)), "local_created" INTEGER NOT NULL DEFAULT 0 CHECK ("local_created" IN (0, 1)), "sync_base_updated_utc" TEXT NULL, "last_synced_at_utc" TEXT NULL, "created_local_at_utc" TEXT NOT NULL, "updated_local_at_utc" TEXT NOT NULL, PRIMARY KEY ("account_id", "task_list_id", "id"), FOREIGN KEY(account_id, task_list_id) REFERENCES task_lists(account_id, id) ON DELETE CASCADE);
