CREATE TABLE "web_cal_subscriptions" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE, "calendar_source_id" TEXT NOT NULL REFERENCES calendar_sources (id) ON DELETE CASCADE, "feed_fingerprint" TEXT NOT NULL UNIQUE, "safe_origin" TEXT NOT NULL, "validator_target_fingerprint" TEXT NULL, "etag" TEXT NULL, "last_modified" TEXT NULL, "content_type" TEXT NULL, "snapshot_ics_body" TEXT NOT NULL, "raw_body_hash" TEXT NOT NULL, "semantic_hash" TEXT NOT NULL, "refresh_mode" TEXT NOT NULL, "server_refresh_interval_seconds" INTEGER NULL, "next_refresh_at_utc" TEXT NOT NULL, "last_checked_at_utc" TEXT NULL, "last_successful_sync_at_utc" TEXT NULL, "last_changed_at_utc" TEXT NULL, "consecutive_failure_count" INTEGER NOT NULL DEFAULT 0, "last_failure_code" TEXT NULL, "last_failure_http_status" INTEGER NULL, "generation" INTEGER NOT NULL DEFAULT 1, "parser_version" INTEGER NOT NULL DEFAULT 1, "projection_version" INTEGER NOT NULL DEFAULT 1, "projection_range_start_utc" TEXT NULL, "projection_range_end_utc" TEXT NULL, "created_at_utc" TEXT NOT NULL, "updated_at_utc" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("account_id"), UNIQUE ("calendar_source_id"));
