CREATE TABLE "android_notification_mappings" ("schedule_id" TEXT NOT NULL, "generation" TEXT NOT NULL, "platform_id" INTEGER NOT NULL UNIQUE, "scheduled_at_utc" INTEGER NOT NULL, "state" TEXT NOT NULL DEFAULT 'scheduled', "updated_at_utc" INTEGER NOT NULL, PRIMARY KEY ("schedule_id"));
