CREATE TABLE "notification_issues" ("id" TEXT NOT NULL, "account_id" TEXT NULL, "kind" TEXT NOT NULL, "revision" TEXT NOT NULL, "submitted_revision" TEXT NULL, "submitted_private" INTEGER NOT NULL DEFAULT 0 CHECK ("submitted_private" IN (0, 1)), "retry_at_utc" INTEGER NULL, "native_id" INTEGER NULL, "cleanup_pending" INTEGER NOT NULL DEFAULT 0 CHECK ("cleanup_pending" IN (0, 1)), PRIMARY KEY ("id"));
