CREATE TABLE bm_contact_accounts(
      id TEXT NOT NULL PRIMARY KEY,
      data TEXT NOT NULL
    );
CREATE TABLE bm_contact_account_links(
      contact_account_id TEXT NOT NULL PRIMARY KEY
        REFERENCES bm_contact_accounts(id) ON DELETE CASCADE,
      busymax_account_id TEXT REFERENCES accounts(id) ON DELETE SET NULL,
      reuse_authorization INTEGER NOT NULL DEFAULT 0
        CHECK(reuse_authorization IN (0, 1))
    );
CREATE TABLE bm_contact_sources(
      source_key TEXT NOT NULL PRIMARY KEY,
      account_id TEXT NOT NULL
        REFERENCES bm_contact_accounts(id) ON DELETE CASCADE,
      data TEXT NOT NULL
    );
CREATE TABLE bm_contact_records(
      identity_key TEXT NOT NULL PRIMARY KEY,
      account_id TEXT NOT NULL
        REFERENCES bm_contact_accounts(id) ON DELETE CASCADE,
      source_key TEXT NOT NULL
        REFERENCES bm_contact_sources(source_key) ON DELETE CASCADE,
      name TEXT NOT NULL,
      search_text TEXT NOT NULL,
      data TEXT NOT NULL,
      projection TEXT NOT NULL,
      seen_scan TEXT
    );
CREATE INDEX bm_contact_records_name_idx ON bm_contact_records(name COLLATE NOCASE, identity_key);
CREATE INDEX bm_contact_records_account_idx ON bm_contact_records(account_id, name COLLATE NOCASE, identity_key);
CREATE INDEX bm_contact_records_source_idx ON bm_contact_records(source_key, name COLLATE NOCASE, identity_key);
CREATE TABLE bm_contact_mutations(
      id TEXT NOT NULL PRIMARY KEY,
      account_id TEXT NOT NULL
        REFERENCES bm_contact_accounts(id) ON DELETE CASCADE,
      source_key TEXT NOT NULL,
      data TEXT NOT NULL
    );
CREATE INDEX bm_contact_mutations_account_idx ON bm_contact_mutations(account_id, source_key);
CREATE TABLE bm_contact_sync_states(
      source_key TEXT NOT NULL PRIMARY KEY
        REFERENCES bm_contact_sources(source_key) ON DELETE CASCADE,
      data TEXT NOT NULL
    );
CREATE TABLE bm_contact_drafts(
      id TEXT NOT NULL PRIMARY KEY,
      source_key TEXT NOT NULL
        REFERENCES bm_contact_sources(source_key) ON DELETE CASCADE,
      data TEXT NOT NULL
    );
CREATE TABLE bm_contact_source_preferences(
      source_key TEXT NOT NULL PRIMARY KEY
        REFERENCES bm_contact_sources(source_key) ON DELETE CASCADE,
      enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0, 1))
    );
