CREATE INDEX idx_calendar_sources_dav_collection ON calendar_sources(dav_collection_id);
CREATE UNIQUE INDEX idx_calendar_events_provider_id ON calendar_events(account_id, provider, provider_calendar_id, provider_event_id, provider_original_start_key);
CREATE INDEX idx_calendar_events_range ON calendar_events(account_id, calendar_source_id, all_day, start_date, start_date_time, end_date, end_date_time);
CREATE INDEX idx_calendar_events_dirty ON calendar_events(account_id, sync_status, is_deleted);
CREATE INDEX idx_calendar_events_dav_occurrence ON calendar_events(dav_object_id, dav_component_id, occurrence_key);
CREATE UNIQUE INDEX idx_sync_cursors_scope ON sync_cursors(account_id, provider, transport, sync_scope_kind, IFNULL(dav_collection_id, ''), IFNULL(projection_source_id, ''), cursor_kind, IFNULL(range_start, ''), IFNULL(range_end, ''));
CREATE INDEX idx_pending_ops_dav_replay ON pending_ops(account_id, dav_collection_id, state, next_attempt_at_utc, created_at_utc);
CREATE INDEX idx_notification_schedule_due ON notification_schedule(scheduled_at_utc, sent_at_utc, dismissed_at_utc, snoozed_until_utc);
CREATE INDEX idx_webcal_subscriptions_due ON web_cal_subscriptions(next_refresh_at_utc);
CREATE TRIGGER location_event_delete AFTER DELETE ON calendar_events BEGIN DELETE FROM location_resolutions WHERE kind = 'event' AND account_id = OLD.account_id AND source_id = OLD.calendar_source_id AND item_id = OLD.id; END;
CREATE TRIGGER location_event_invalidate AFTER UPDATE OF location, is_deleted ON calendar_events WHEN NEW.location IS NOT OLD.location OR NEW.is_deleted = 1 BEGIN DELETE FROM location_resolutions WHERE kind = 'event' AND account_id = OLD.account_id AND source_id = OLD.calendar_source_id AND item_id = OLD.id; END;
CREATE TRIGGER location_event_identity AFTER UPDATE OF id, account_id, calendar_source_id ON calendar_events BEGIN UPDATE OR REPLACE location_resolutions SET account_id = NEW.account_id, source_id = NEW.calendar_source_id, item_id = NEW.id WHERE kind = 'event' AND account_id = OLD.account_id AND source_id = OLD.calendar_source_id AND item_id = OLD.id; END;
CREATE TRIGGER location_task_delete AFTER DELETE ON tasks BEGIN DELETE FROM location_resolutions WHERE kind = 'task' AND account_id = OLD.account_id AND source_id = OLD.task_list_id AND item_id = OLD.id; END;
CREATE TRIGGER location_task_invalidate AFTER UPDATE OF task_location, pending_delete ON tasks WHEN NEW.task_location IS NOT OLD.task_location OR NEW.pending_delete = 1 BEGIN DELETE FROM location_resolutions WHERE kind = 'task' AND account_id = OLD.account_id AND source_id = OLD.task_list_id AND item_id = OLD.id; END;
CREATE TRIGGER location_task_identity AFTER UPDATE OF id, account_id, task_list_id ON tasks BEGIN UPDATE OR REPLACE location_resolutions SET account_id = NEW.account_id, source_id = NEW.task_list_id, item_id = NEW.id WHERE kind = 'task' AND account_id = OLD.account_id AND source_id = OLD.task_list_id AND item_id = OLD.id; END;
PRAGMA user_version = 21;
